.cbf-pdf-panel {
  flex: 1;
  min-width: 0;
  border-right: 1px solid var(--color-border);
  display: flex;
  flex-direction: column;
  position: relative;
}
.cbf-pdf-panel {
  background: var(--color-surface-sunken, #f8f9fb);
}
.cbf-pdf-panel[hidden] {
  display: none;
}
.cbf-pdf-drop {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: var(--spacing-300);
  text-align: center;
  margin: var(--spacing-500);
  padding: var(--spacing-700) var(--spacing-600);
  border: 2px dashed var(--color-border);
  border-radius: var(--radius-100);
  background: var(--color-surface);
  transition:
    border-color 0.15s ease,
    background 0.15s ease;
}
.cbf-pdf-drop__input {
  position: absolute;
  width: 1px;
  height: 1px;
  opacity: 0;
  pointer-events: none;
}
.cbf-pdf-drop__icon {
  color: var(--color-text-muted);
}
.cbf-pdf-drop__heading {
  margin: 0;
  font-size: 16px;
  font-weight: var(--font-weight-semibold);
  color: var(--color-text-primary);
}
.cbf-pdf-drop__sub {
  margin: 0;
  font-size: 14px;
  color: var(--color-text-secondary);
}
.cbf-pdf-drop__browse {
  color: var(--color-secondary);
  font-weight: var(--font-weight-semibold);
  text-decoration: underline;
  text-underline-offset: 2px;
}
.cbf-pdf-drop__hint {
  margin: 0;
  font-size: 12px;
  color: var(--color-text-muted);
}
.cbf-pdf-drop__error {
  width: 100%;
  max-width: 360px;
  margin-top: var(--spacing-200);
  margin-inline: auto;
  text-align: left;
}
.cbf-pdf-drop__error[hidden] {
  display: none;
}
.cbf-pdf-viewer {
  flex: 1;
  display: flex;
  flex-direction: column;
  min-height: 0;
}
.cbf-pdf-viewer[hidden] {
  display: none;
}

.esa-button {
  --_btn-height: var(--form-height-md, 40px);
  --_btn-padding-x: var(--form-padding-x-md, 16px);
  --_btn-font-size: var(--form-font-size-md, 14px);
  --_btn-radius: var(--form-radius-md, 6px);
  --_accent: var(--color-primary, #46a758);
  --_accent-hover: var(--color-primary-hover, #3e9b4f);
  --_on: var(--color-text-inverse, #ffffff);
  --_accent-text: var(--_accent);
  --_btn-tint-hover: color-mix(in srgb, var(--_accent) 8%, transparent);
  --_btn-tint-active: color-mix(in srgb, var(--_accent) 14%, transparent);
  display: inline-block;
}
.esa-button--color-danger {
  --_accent: var(--color-danger);
  --_accent-hover: var(--color-danger-hover);
  --_accent-text: var(--color-danger-strong);
}
.esa-button__native {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--spacing-200, 8px);
  width: 100%;
  height: var(--_btn-height);
  padding-inline: var(--_btn-padding-x);
  border: 1px solid transparent;
  border-radius: var(--_btn-radius);
  font-size: var(--_btn-font-size);
  font-family: var(--font-sans, system-ui, sans-serif);
  font-weight: var(--font-weight-medium, 500);
  line-height: 1;
  text-decoration: none;
  cursor: pointer;
  transition:
    background var(--transition-fast, 0.15s ease),
    border-color var(--transition-fast, 0.15s ease);
  -webkit-appearance: none;
  appearance: none;
}
.esa-button--appearance-outline .esa-button__native,
.esa-button--appearance-dashed .esa-button__native {
  background: transparent;
  color: var(--_accent-text);
  border-color: var(--_accent);
}
.esa-button__label {
  white-space: nowrap;
}
.esa-button--color-secondary {
  --_accent: var(--color-secondary);
  --_accent-hover: var(--color-secondary-hover);
  --_on: var(--color-secondary-on-fill, var(--color-gray-12));
  --_accent-text: var(--color-secondary-strong);
}
.esa-button--color-primary {
  --_accent-text: var(--color-primary-strong);
}
.esa-button--appearance-fill .esa-button__native {
  background: var(--_accent);
  color: var(--_on);
  border-color: transparent;
}
.cbf-page-title {
  margin: 0 0 var(--spacing-400);
  font-family: var(--font-display);
  font-weight: var(--font-weight-medium);
  font-size: 40px;
  line-height: 1;
  letter-spacing: -1px;
  color: var(--color-surface-inverse);
}
.cbf-form-lock {
  display: flex;
  align-items: center;
  gap: var(--spacing-250);
  margin-bottom: var(--spacing-500);
  padding: var(--spacing-300) var(--spacing-400);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-100);
  background: var(--color-surface-sunken, #f8f9fb);
  font-size: 13px;
  color: var(--color-text-muted);
  line-height: 1.4;
}
.cbf-form-lock svg {
  flex: none;
  color: var(--color-text-muted);
}
.cbf-form-lock[hidden],
.cbf-form-lock__msg--narrow,
.cbf-form-lock__upload-btn {
  display: none;
}
.cbf-mobile-pdf-input {
  position: absolute;
  width: 1px;
  height: 1px;
  opacity: 0;
  pointer-events: none;
}
.cbf-form-fields {
  display: flex;
  flex-direction: column;
  gap: var(--spacing-500);
}
.cbf-final-invoice {
  padding: var(--spacing-400) var(--spacing-450, var(--spacing-400));
  border: 1px solid var(--color-border);
  border-radius: var(--radius-100);
  background: var(--color-surface-sunken, #f8f9fb);
  transition:
    border-color 0.15s ease,
    background 0.15s ease,
    box-shadow 0.15s ease;
}
.cbf-support-docs-group__label {
  margin: 0 0 var(--spacing-050);
  font-size: var(--type-size-200, 13px);
  font-weight: var(--font-weight-medium);
  color: var(--color-text-secondary);
}
.cbf-optional {
  font-size: 13px;
  font-weight: var(--font-weight-regular);
  color: var(--color-text-muted);
}
.cbf-support-docs-group__desc {
  margin: 0 0 var(--spacing-300);
  font-size: 13px;
  color: var(--color-text-muted);
  line-height: 1.5;
}
.cbf-support-docs {
  border: 1px solid var(--color-border);
  border-radius: var(--radius-100);
  overflow: hidden;
  transition:
    border-color 0.12s ease,
    background 0.12s ease;
}
.cbf-support-docs__add {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: var(--spacing-200);
  font-size: 14px;
  color: var(--color-text-secondary);
  padding: var(--spacing-400);
  width: 100%;
  transition:
    background 0.12s ease,
    color 0.12s ease;
}
.cbf-support-docs__add svg {
  flex: none;
  color: var(--color-secondary);
}
.cbf-support-docs__add-text strong {
  font-weight: var(--font-weight-semibold);
  color: var(--color-secondary);
}
.cbf-docs-input {
  position: absolute;
  width: 1px;
  height: 1px;
  opacity: 0;
  pointer-events: none;
}
.cbf-step-actions {
  display: flex;
  align-items: center;
  gap: var(--spacing-300);
  margin-top: var(--spacing-700);
  padding-top: var(--spacing-500);
  border-top: 1px solid var(--color-border);
}
.cbf-step-actions [data-wizard-save-draft] {
  margin-left: auto;
}
.cbf-support-docs__add:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

